import {db,fs} from '/tmp/handoff-eleven.mjs';process.loadEnvFile('.env.local');const phones=['+14162269770','+14165341124'];const out=[];for(const phone of phones){const response=await fetch('https://api.telnyx.com/v2/number_lookup/'+encodeURIComponent(phone)+'?type=carrier',{headers:{Authorization:'Bearer '+process.env.TELNYX_API_KEY.trim()}});if(!response.ok)throw Error('Lookup '+response.status);const d=(await response.json()).data;const peers=await db('market_contacts',{phone:'eq.'+phone,select:'id,name,do_not_contact'});out.push({phone,valid:d.valid_number,country:d.country_code,type:d.carrier?.type,peers});}fs.writeFileSync('artifacts/realtor-batch-20261009/failed-alternate-verification.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));
